CREATE TABLE branches(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(160) NOT NULL);
INSERT INTO branches(name) VALUES ('Sucursal principal');
CREATE TABLE users(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username VARCHAR(80) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, role VARCHAR(30) NOT NULL CHECK(role IN ('ADMIN','SUPERVISOR','CASHIER','INVENTORY','ACCOUNTANT')), branch_id BIGINT NOT NULL REFERENCES branches, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE products(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, sku VARCHAR(80) UNIQUE NOT NULL, name VARCHAR(200) NOT NULL, generic_name VARCHAR(200) NOT NULL DEFAULT '', base_unit VARCHAR(50) NOT NULL, category VARCHAR(100) NOT NULL DEFAULT '', requires_rx BOOLEAN NOT NULL DEFAULT FALSE, controlled BOOLEAN NOT NULL DEFAULT FALSE, fractional BOOLEAN NOT NULL DEFAULT FALSE, minimum_stock BIGINT NOT NULL DEFAULT 10 CHECK(minimum_stock>=0), active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE presentations(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_id BIGINT NOT NULL REFERENCES products, name VARCHAR(80) NOT NULL, factor BIGINT NOT NULL CHECK(factor>0), price NUMERIC(14,2) NOT NULL CHECK(price>=0), barcode VARCHAR(100) UNIQUE, sale_enabled BOOLEAN NOT NULL DEFAULT TRUE, fractional BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE suppliers(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(200) NOT NULL, nit VARCHAR(40) NOT NULL DEFAULT '', contact VARCHAR(200) NOT NULL DEFAULT '', lead_days INT NOT NULL DEFAULT 3 CHECK(lead_days>=0));
CREATE TABLE receipts(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, branch_id BIGINT NOT NULL REFERENCES branches, supplier_id BIGINT NOT NULL REFERENCES suppliers, document VARCHAR(100) NOT NULL, actor VARCHAR(80) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(supplier_id,document));
CREATE TABLE lots(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, branch_id BIGINT NOT NULL REFERENCES branches, product_id BIGINT NOT NULL REFERENCES products, receipt_id BIGINT NOT NULL REFERENCES receipts, code VARCHAR(100) NOT NULL, expires_on DATE NOT NULL, state VARCHAR(30) NOT NULL DEFAULT 'AVAILABLE' CHECK(state IN ('AVAILABLE','QUARANTINE','BLOCKED','DAMAGED','RECALLED')), qty_base BIGINT NOT NULL CHECK(qty_base>=0), unit_cost NUMERIC(18,6) NOT NULL CHECK(unit_cost>=0), received_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX lots_fefo ON lots(branch_id,product_id,expires_on,id);
CREATE TABLE cash_sessions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, branch_id BIGINT NOT NULL REFERENCES branches, actor VARCHAR(80) NOT NULL, opening NUMERIC(14,2) NOT NULL CHECK(opening>=0), opened_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, closed_at TIMESTAMP WITH TIME ZONE, counted NUMERIC(14,2), expected NUMERIC(14,2), difference NUMERIC(14,2));
CREATE UNIQUE INDEX one_open_cash ON cash_sessions(branch_id,actor) WHERE closed_at IS NULL;
CREATE TABLE sales(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, branch_id BIGINT NOT NULL REFERENCES branches, cash_session_id BIGINT NOT NULL REFERENCES cash_sessions, actor VARCHAR(80) NOT NULL, idempotency_key VARCHAR(80) NOT NULL, request_hash VARCHAR(64) NOT NULL, total NUMERIC(14,2) NOT NULL, method VARCHAR(30) NOT NULL CHECK(method IN ('CASH','CARD','TRANSFER')), tendered NUMERIC(14,2) NOT NULL, change_amount NUMERIC(14,2) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(branch_id,idempotency_key));
CREATE TABLE sale_lines(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, sale_id BIGINT NOT NULL REFERENCES sales, presentation_id BIGINT NOT NULL REFERENCES presentations, product_name VARCHAR(200) NOT NULL, presentation_name VARCHAR(80) NOT NULL, quantity BIGINT NOT NULL CHECK(quantity>0), factor BIGINT NOT NULL CHECK(factor>0), price NUMERIC(14,2) NOT NULL);
CREATE TABLE allocations(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, line_id BIGINT NOT NULL REFERENCES sale_lines, lot_id BIGINT NOT NULL REFERENCES lots, quantity BIGINT NOT NULL CHECK(quantity>0), cost NUMERIC(18,6) NOT NULL);
CREATE TABLE stock_movements(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, branch_id BIGINT NOT NULL REFERENCES branches, lot_id BIGINT NOT NULL REFERENCES lots, kind VARCHAR(30) NOT NULL, delta_base BIGINT NOT NULL CHECK(delta_base<>0), reference VARCHAR(100) NOT NULL, actor VARCHAR(80) NOT NULL, reason VARCHAR(300) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_logs(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, branch_id BIGINT NOT NULL REFERENCES branches, actor VARCHAR(80) NOT NULL, action VARCHAR(80) NOT NULL, reference VARCHAR(100) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE outbox_events(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, event_type VARCHAR(80) NOT NULL, aggregate_id BIGINT NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'PENDING', attempts INT NOT NULL DEFAULT 0, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
